import { franziAnswer, startFranziAI, franziReady, campusAnswer } from './franzi.js';
import { icon } from './icons.js';
import { DEMO_USER, DEMO_PROFILES, PEOPLE, SPOTS, demoPosts } from './data.js';
import { createDemoWorld, emptyDemoAccount, demoPerson, hydrateDemoPosts, visibleDemoChats } from './demo.js';
import { api, configured } from './api.js';
import { escapeHtml as e, safeImage, initials, dateLabel, timeLabel, relative, filterPosts, validatePost, makeICS, readLocal, saveLocal, TYPES, CATEGORIES } from './core.js';
const $ = s => document.querySelector(s);
const demoWorld=createDemoWorld(readLocal('fhv-demo-v2',null),readLocal('fhv-demo-v1',null));
let activeDemoId;try{activeDemoId=sessionStorage.getItem('fhv-demo-active');}catch{}
if(!demoWorld.profiles.some(p=>p.id===activeDemoId))activeDemoId=demoWorld.profiles[0].id;
const demoAccount=demoWorld.accounts[activeDemoId]||emptyDemoAccount();
const state = {mode:'demo',user:{...demoPerson(demoWorld,activeDemoId)},posts:hydrateDemoPosts(demoWorld),joined:demoAccount.joined,saved:demoAccount.saved,liked:demoAccount.liked,comments:demoWorld.comments,chats:demoWorld.chats,messages:demoWorld.messages,invitations:demoAccount.invitations,tab:['feed','trade','activities','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'feed',filter:'Alle',query:'',activityTab:'Entdecken',tradeTab:'Angebote',overlay:null,selected:null,busy:false,loading:false,authMode:'login',createType:'activity',createCategory:'Campus',currentChat:null,noticeRead:false};
let deferredInstall, chatInterval, lastFocus;
const fhvMark = `<svg viewBox="0 0 460 460" fill="currentColor" aria-hidden="true"><path d="M10.8 346.8h337.5V234.3H10.8V121.7h337.6V9.1H461v450.2H10.9l-.1-112.5z"/></svg>`;
const logo = `<span class="wordmark" role="img" aria-label="FHV Friends"><span class="logo-eyebrow">FHV</span><span class="logo-name">${fhvMark}<span>riends<span class="logo-dot">.</span></span></span></span>`;
const avatar = (person,size='') => `<span class="avatar ${person?.color||'blue'} ${size}" aria-hidden="true">${safeImage(person?.avatar_data)?`<img src="${e(safeImage(person.avatar_data))}" alt="">`:person?.role==='oh'?'ÖH':e(initials(person?.name))}</span>`;
const isOh = () => ['oh','admin'].includes(state.user?.role);
const isDemo = () => state.mode==='demo';
const joined = id => state.joined.includes(id);
const count = p => p.join_count || 0;
const full = p => p.capacity && count(p)>=p.capacity && !joined(p.id);
const pendingInvites = () => state.invitations.filter(i=>i.status==='pending');
function persist(){
 if(!isDemo())return;
 demoWorld.profiles=demoWorld.profiles.map(p=>p.id===state.user.id?{...state.user,role:'student'}:p);
 demoWorld.accounts[state.user.id]={joined:state.joined,saved:state.saved,liked:state.liked,invitations:state.invitations};
 demoWorld.posts=state.posts.map(({author,...p})=>p);
 Object.assign(demoWorld,{comments:state.comments,chats:state.chats,messages:state.messages});
 if(!saveLocal('fhv-demo-v2',demoWorld))throw new Error('Gerätespeicher voll. Bitte ein kleineres Foto verwenden.');
 const updated=hydrateDemoPosts(demoWorld);state.posts.forEach(p=>Object.assign(p,updated.find(v=>v.id===p.id)||{}));
}
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500); }
function empty(title,description,action='create',button='Etwas starten') { return `<div class="empty-state"><span class="empty-icon">${icon('spark',32)}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="btn primary" data-action="${action}">${button}</button>`:''}</div>`; }
function nav() { return `<nav class="bottom-nav" aria-label="Hauptnavigation">${[['feed','home','Home / Feed'],['trade','trade','Trade / Help'],['create','plus','Erstellen'],['activities','calendar','Activities'],['profile','user','Profile']].map(([id,ico,label])=>`<button class="nav-item ${id==='create'?'nav-create':''} ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="${id==='create'?'create':'nav'}" data-tab="${id}" aria-label="${label}"><span class="nav-icon">${icon(ico,id==='create'?29:23)}</span><span class="nav-label">${label}</span></button>`).join('')}</nav>`; }
function sidebar(){return `<aside class="sidebar"><button class="brand" data-action="nav" data-tab="feed" aria-label="FHV Friends Startseite">${logo}</button><nav aria-label="Desktop-Navigation">${[['feed','home','Feed'],['trade','trade','Trade / Help'],['activities','calendar','Activities'],['profile','user','Profil']].map(([id,ico,label])=>`<button class="side-link ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="nav" data-tab="${id}">${icon(ico)}<span>${label}</span></button>`).join('')}<button class="side-link" data-action="people">${icon('people')}<span>Kontakte</span></button><button class="side-link" data-action="franzi">${icon('franzi')}<span>Franzi</span></button><button class="side-link" data-action="inbox">${icon('chat')}<span>Nachrichten</span></button></nav><button class="btn primary side-create" data-action="create">${icon('plus',19)} Beitrag erstellen</button><div class="sidebar-bottom">${isDemo()?`<button class="side-user" data-action="test-accounts">${avatar(state.user)}<span><strong>${e(state.user.name)}</strong><small>Testprofil wechseln</small></span>${icon('down',16)}</button>`:''}<button class="side-link" data-action="install">${icon('download',18)}<span>App installieren</span></button><button class="sidebar-about" data-action="about">Über FHV Friends</button></div></aside>`;}
function header(){const title={feed:'Feed',trade:'Trade / Help',activities:'Activities',profile:'Mein Profil'}[state.tab]||'Feed';return `<header class="page-header page-${state.tab}"><div class="mobile-brand">${logo}</div><div class="header-main"><div class="page-title"><span class="page-eyebrow">FHV / COMMUNITY</span><h1>${title}</h1></div><div class="header-actions"><button class="icon-btn franzi-button" data-action="franzi" aria-label="Franzi öffnen">${icon('franzi',25)}<span></span></button><button class="icon-btn" data-action="inbox" aria-label="Nachrichten öffnen">${icon('chat')}</button><button class="icon-btn notification-btn" data-action="notifications" aria-label="Einladungen und Neuigkeiten">${icon('bell')}${!state.noticeRead&&pendingInvites().length?'<span class="notification-dot"></span>':''}</button></div></div></header>`;}
function statusBanner(){return isDemo()?`<div class="status-bar demo-bar"><span>Demo · nur auf diesem Gerät</span><div><button data-action="test-accounts">${e(state.user.name)} ${icon('down',12)}</button><button data-action="auth">Anmelden</button></div></div>`:'';}
function chips(items,selected,action='filter') { return `<div class="chips" role="group" aria-label="Filtern">${items.map(f=>`<button class="chip ${selected===f?'selected':''}" aria-pressed="${selected===f}" data-action="${action}" data-value="${f}">${f}</button>`).join('')}</div>`; }
function searchBox(placeholder='Wonach suchst du?') { return `<label class="search-box">${icon('search',20)}<input id="search" type="search" value="${e(state.query)}" placeholder="${placeholder}" aria-label="${placeholder}" autocomplete="off"><kbd>/</kbd></label>`; }
function authorLine(p) { return `<div class="author-line"><button class="person-avatar" data-action="person" data-id="${p.author_id}" aria-label="Profil von ${e(p.author?.name)} öffnen">${avatar(p.author)}</button><div><button class="author-name" data-action="person" data-id="${p.author_id}"><strong>${e(p.author?.name || 'Campus-Mitglied')}${p.pinned||p.author?.role==='oh'?'<span class="verified" title="Verifizierte ÖH">'+icon('check',11)+'</span>':''}</strong></button><small>${e(p.author?.course || (isDemo()?'Testprofil':'FHV'))} · ${relative(p.created_at)}</small></div><button class="icon-btn small card-more" data-action="post-menu" data-id="${p.id}" aria-label="Beitragsoptionen">${icon('more',20)}</button></div>`; }
function bookmarkButton(p) { const saved=state.saved.includes(p.id);return `<button class="icon-btn small ${saved?'is-saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Nicht mehr merken':'Beitrag merken'}" aria-pressed="${saved}">${icon('bookmark',19)}</button>`; }
function hero(p){
 return `<article class="pinned-post"><div class="pinned-feature"><div class="pinned-label">${icon('pin',15)} ÖH FHV <span>ANGEPINNT</span></div><button class="text-link pinned-title" data-action="detail" data-id="${p.id}"><h2>${e(p.title)}</h2></button><div class="pinned-bottom"><span>${icon('map',15)} ${e(p.location)}</span><button class="btn primary" data-action="detail" data-id="${p.id}">Ansehen</button></div></div><button class="feature-date" data-action="detail" data-id="${p.id}" aria-label="${e(p.title)} ansehen"><span>${dateLabel(p.starts_at,{weekday:'short'}).split(',')[0]}</span><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'long'}).replace(/\d+\.?\s*/,'')}</small><span>${timeLabel(p.starts_at)} Uhr</span></button></article>`;
}

function miniAvatars(){return '';}
function postCard(p,{compact=false}={}){
 const activity=p.type==='activity',ride=p.category==='Mitfahren',hasPhoto=Boolean(safeImage(p.image_data));
 const tone={activity:({Mitfahren:'green',Kultur:'lavender',Campus:'yellow',Sport:'coral'}[p.category]||'blue'),food:'green',trade:'lavender',help:'yellow',life:'coral'}[p.type];
 const label=ride?'Fahrgemeinschaft':p.type==='trade'?(Number(p.price)>0?'Zu verkaufen':'Zu verschenken'):TYPES[p.type];
 const liked=state.liked.includes(p.id),poster=activity&&!hasPhoto;
 const cover=hasPhoto?`<button class="card-visual" data-action="detail" data-id="${p.id}" aria-label="${e(p.title)} ansehen"><img src="${e(safeImage(p.image_data))}" alt="${e(p.title)}" loading="lazy"></button>`:poster?`<button class="event-poster ${tone}" data-action="detail" data-id="${p.id}"><span class="poster-top"><span>${e(ride?'Mitfahren':p.category)}</span><span>${dateLabel(p.starts_at,{weekday:'short'})}</span></span><h3>${e(p.title)}</h3><span class="poster-bottom"><span>${icon(ride?'car':'calendar',18)} ${timeLabel(p.starts_at)} Uhr</span>${icon(ride?'car':p.category==='Lernen'?'book':p.category==='Kultur'?'coffee':'people',42)}</span></button>`:'';
 return `<article class="post-card tone-${tone} ${poster?'has-poster':''} ${compact?'compact':''}">${authorLine(p)}${cover}<div class="card-body"><div class="card-kicker"><span class="type-label ${tone}">${e(label)}</span>${p.type==='help'?`<span class="secondary-label">${p.help_direction==='request'?'Sucht Hilfe':'Bietet Hilfe'}</span>`:''}${p.example?'<span class="example-label">Beispiel</span>':''}${p.status==='reserved'?'<span class="reserved-label">Reserviert</span>':''}</div>${!poster?`<button class="text-link card-title" data-action="detail" data-id="${p.id}"><h3>${e(p.title)}</h3></button>`:''}<p class="card-description">${e(p.description)}</p><div class="card-meta">${icon('map',15)} ${e(p.location)}${ride?`<span class="ride-route">${e(p.ride_destination)} · ${Math.max(0,p.capacity-count(p))} frei · ${Number(p.price).toLocaleString('de-AT')} €</span>`:''}</div><div class="card-footer"><button class="like-btn ${liked?'liked':''}" aria-label="Gefällt mir" aria-pressed="${liked}" data-action="like" data-id="${p.id}">${icon('heart',19)}<span>${Number(p.likes||0)}</span></button>${activity?`<span class="going-label">${count(p)} dabei</span>`:`<span class="price-label">${p.price?`${Number(p.price).toLocaleString('de-AT')} €`:'Kostenlos'}</span>`}<div class="card-footer-right">${bookmarkButton(p)}<button class="btn small ${joined(p.id)?'joined':'soft'}" data-action="detail" data-id="${p.id}">${activity?(joined(p.id)?icon('check',14)+' Dabei':full(p)?'Ausgebucht':'Mitmachen'):p.type==='help'?'Kontakt':'Ansehen'}</button></div></div></div></article>`;
}

function feed() { const all = filterPosts(state.posts,{tab:'feed',filter:state.filter,query:state.query}); const featured = state.filter==='Alle'&&!state.query?all.find(p=>p.pinned&&p.type==='activity'):null; const rest=all.filter(p=>p.id!==featured?.id); return `<div class="campus-actions"><button data-action="discover">${icon('calendar',24)}<span>Aktivitäten</span></button><button data-action="rides">${icon('car',24)}<span>Mitfahren</span></button><button data-action="market">${icon('trade',24)}<span>Marktplatz</span></button><button data-action="people">${icon('people',24)}<span>Leute finden</span></button></div>${searchBox('Campus durchsuchen')}${chips(['Alle','Aktivitäten','Verkaufen','Verschenken','Essen','Hilfe','Campusleben'],state.filter)}<div id="feed-results">${featured?hero(featured):''}<div class="section-heading"><h2>${state.query?'Deine Suchergebnisse':state.filter==='Alle'?'Beiträge':state.filter}</h2><span>${rest.length} Beiträge</span></div><div class="post-grid">${rest.length?rest.map(p=>postCard(p)).join(''):empty('Keine Beiträge gefunden.','Versuche einen anderen Suchbegriff.')}</div></div>`; }
function trade(){const posts=filterPosts(state.posts,{tab:'trade',filter:state.filter,query:state.query});return `<div class="segment-control">${['Angebote','Campus-Spots'].map(v=>`<button class="${state.tradeTab===v?'selected':''}" data-action="trade-tab" data-value="${v}">${v}</button>`).join('')}</div>${state.tradeTab==='Campus-Spots'?`<div class="spot-list">${SPOTS.map(p=>`<article class="spot-card"><span class="spot-icon">${icon(p.icon,24)}</span><div><h3>${p.name}</h3><p>${p.description}</p></div></article>`).join('')}</div><p class="muted">Lebensmittel bitte persönlich übergeben.</p>`:`${searchBox('Angebote und Hilfe suchen')}${chips(['Alle','Verkaufen','Verschenken','Essen','Hilfe'],state.filter)}<div class="section-heading"><h2>${state.filter==='Alle'?'Angebote':state.filter}</h2><button class="text-link" data-action="create-trade">${icon('plus',16)} Anbieten</button></div><div class="post-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('Keine Angebote gefunden.','Du kannst selbst etwas anbieten.')}</div>`}`;}
function invitationCard(inv) { const p=state.posts.find(x=>x.id===inv.post_id);if(!p)return '';const who=p.author?.name||'Campus'; return `<article class="invitation-card ${inv.sender_id==='demo-oh'||p.pinned?'yellow':'lavender'}"><span class="tiny-label">${e(who)} ${p.pinned?'· OFFICIAL':'HAT DICH EINGELADEN'}</span><h3>${e(p.subtitle||p.title)}</h3><p>${dateLabel(p.starts_at,{weekday:'short'})} · ${timeLabel(p.starts_at)}</p><small>${e(p.location)} · ${count(p)} dabei</small><div class="invitation-actions"><button class="btn primary" data-action="accept" data-id="${inv.id}">${icon('check',16)} Einladung annehmen</button><button class="btn translucent" data-action="decline" data-id="${inv.id}">Nicht jetzt</button></div></article>`; }
function activities(){const invites=pendingInvites();const posts=filterPosts(state.posts,{tab:'activities',filter:state.filter,query:state.query,activityTab:state.activityTab,userId:state.user.id,joined:state.joined});return `<div class="segment-control activity-segments">${['Entdecken','Einladungen','Meine Pläne'].map(v=>`<button class="${state.activityTab===v?'selected':''}" data-action="activity-tab" data-value="${v}">${v}${v==='Einladungen'&&invites.length?`<span class="count-badge">${invites.length}</span>`:''}</button>`).join('')}</div>${state.activityTab==='Einladungen'?`<div class="invitation-list">${invites.length?invites.map(invitationCard).join(''):empty('Keine offenen Einladungen.','',null)}</div>`:`${searchBox('Aktivitäten suchen')}${chips(CATEGORIES,state.filter)}<div class="section-heading"><h2>${state.activityTab==='Meine Pläne'?'Meine Pläne':'Nächste Aktivitäten'}</h2><span>${posts.length}</span></div><div class="post-grid activity-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('Noch keine Aktivitäten.','',state.activityTab==='Meine Pläne'?'discover':'create',state.activityTab==='Meine Pläne'?'Entdecken':'Aktivität erstellen')}</div>`}`;}
function profile(){const mine=state.posts.filter(p=>p.author_id===state.user.id);return `<section class="profile-card"><div class="profile-content"><div class="profile-heading">${avatar(state.user,'large')}<button class="btn outline small" data-action="edit-profile">Profil bearbeiten</button></div><h2>${e(state.user.name)}</h2>${state.user.course?`<p class="profile-course">${e(state.user.course)}</p>`:''}<span class="verified-label">${isDemo()?'Testprofil':icon('shield',14)+' FHV-Mail bestätigt'}</span>${state.user.bio?`<p class="profile-bio">${e(state.user.bio)}</p>`:''}<div class="interest-chips">${(state.user.interests||[]).map(v=>`<span>${e(v)}</span>`).join('')}</div><div class="profile-stats"><div><strong>${state.joined.length}</strong><span>Zusagen</span></div><div><strong>${mine.length}</strong><span>Beiträge</span></div><div><strong>${state.saved.length}</strong><span>Gemerkt</span></div></div></div></section><div class="profile-menu"><button data-action="people">${icon('people')}<span><strong>Kontakte</strong><small>Leute finden und anschreiben</small></span>${icon('chevron',18)}</button><button data-action="franzi">${icon('franzi')}<span><strong>Franzi</strong><small>Deine Campus-Assistentin</small></span>${icon('chevron',18)}</button>${isDemo()?`<button data-action="test-accounts">${icon('people')}<span><strong>Testprofil wechseln</strong><small>4 Profile zum Ausprobieren</small></span>${icon('chevron',18)}</button>`:''}<button data-action="saved">${icon('bookmark')}<span><strong>Merkliste</strong></span>${icon('chevron',18)}</button><button data-action="my-posts">${icon('user')}<span><strong>Meine Beiträge</strong></span>${icon('chevron',18)}</button><button data-action="install">${icon('download')}<span><strong>App installieren</strong></span>${icon('chevron',18)}</button><button data-action="about">${icon('shield')}<span><strong>Über FHV Friends</strong></span>${icon('chevron',18)}</button><button data-action="${isDemo()?'auth':'logout'}">${icon('logout')}<span><strong>${isDemo()?'Mit FHV-Mail anmelden':'Abmelden'}</strong></span>${icon('chevron',18)}</button></div>`;}
function rightRail(){return '';}
function render() { $('#app').innerHTML=`<div class="app-shell">${sidebar()}<div class="main-shell">${statusBanner()}<div class="content-layout"><main id="main" tabindex="-1">${header()}<div class="page-content ${state.tab}-page">${state.loading?'<div class="loading-state"><span class="spinner"></span><p>Lädt …</p></div>':({feed,trade,activities,profile}[state.tab]||feed)()}</div></main>${state.tab!=='profile'?rightRail():''}</div></div>${nav()}</div>`; }
function navigate(tab) { state.tab=tab;state.filter='Alle';state.query='';history.replaceState(null,'',`#${tab}`);closeModal();render();window.scrollTo({top:0,behavior:'instant'}); }
function modal(title,body,{wide=false,footer='',label=title,cls=''}={}) { clearInterval(chatInterval); lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''} ${cls}" role="dialog" aria-modal="true" aria-label="${e(label)}"><div class="modal-handle"></div><header class="modal-header"><h2>${e(title)}</h2><button class="icon-btn" data-action="close" aria-label="Schließen">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');$('#overlay').querySelector('button,input,textarea,select')?.focus(); }
function closeModal() { if(state.overlay==='create'&&!state.editingId)saveDraft(false);clearInterval(chatInterval);state.overlay=null;state.selected=null;state.currentChat=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.isConnected&&lastFocus.focus(); }
async function detail(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;state.overlay='detail';state.selected=id;const activity=p.type==='activity';const own=p.author_id===state.user.id; const expired=activity&&new Date(p.starts_at)<new Date();const content=`${safeImage(p.image_data)?`<div class="detail-art"><img src="${e(safeImage(p.image_data))}" alt="${e(p.title)}"><span class="detail-category ${activity?'blue':p.type==='help'?'yellow':'lavender'}">${e(activity?p.category:TYPES[p.type])}</span></div>`:''}<div class="detail-content"><div class="detail-topline">${authorLine(p)}${bookmarkButton(p)}</div><h2 class="detail-title">${e(p.subtitle||p.title)}</h2>${activity?`<div class="detail-date"><span class="date-block"><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'')}</small></span><div><strong>${dateLabel(p.starts_at,{weekday:'long',year:'numeric'})}</strong><span>${timeLabel(p.starts_at)} Uhr · ${p.price?`${p.price} €`:'Kostenlos'}</span><span>${icon('map',13)} ${e(p.location)}</span></div><button class="icon-btn" data-action="calendar" data-id="${p.id}" aria-label="Im Kalender speichern">${icon('calendar',21)}</button></div>`:`<div class="detail-listing-meta"><span>${icon('map',17)} ${e(p.location)}</span><strong>${p.price?`${p.price} €`:'Kostenlos'}</strong></div>`}${p.category==='Mitfahren'?`<div class="ride-detail">${icon('car',24)}<div><strong>${e(p.location)} → ${e(p.ride_destination)}</strong><p>${Math.max(0,p.capacity-count(p))} Plätze frei · ${Number(p.price).toLocaleString('de-AT')} € pro Person</p></div></div>`:''}<p class="detail-description">${e(p.description).replace(/\n/g,'<br>')}</p>${p.type==='food'?'<div class="info-box"><span>'+icon('leaf',22)+'</span><div><strong>Bitte persönlich übergeben.</strong><p>Kläre Zutaten, Allergene und Abholzeit direkt mit der anbietenden Person.</p></div></div>':''}${activity?`<div class="detail-attendees yellow"><div>${miniAvatars()}<strong>${count(p)} ${count(p)===1?'Person ist':'Studierende sind'} dabei</strong></div><p>${p.capacity?`${Math.max(0,p.capacity-count(p))} von ${p.capacity} Plätzen frei.`:''}</p></div>${own?'<div class="host-actions"><button class="btn outline full" data-action="invite-people" data-id="'+p.id+'">'+icon('people',18)+' Leute einladen</button><button class="btn soft full" data-action="group-chat" data-id="'+p.id+'">'+icon('chat',18)+' Gruppenchat öffnen</button></div>':''}${joined(p.id)?`<div class="joined-note">${icon('check',18)} Du bist dabei.</div><div class="detail-secondary-actions"><button class="text-link" data-action="group-chat" data-id="${p.id}">${icon('chat',16)} Gruppenchat</button><button class="text-link danger" data-action="join" data-id="${p.id}">Doch nicht dabei</button></div>`:''}`:''}<section class="comments-section"><h3>Kommentare <span id="comment-count"></span></h3><div id="comments-list"><p class="muted">${isDemo()?'Noch keine Kommentare.':'Kommentare laden …'}</p></div><form id="comment-form" data-post="${p.id}" class="comment-form"><input name="body" required minlength="1" maxlength="1000" placeholder="Kommentar schreiben …" aria-label="Kommentar schreiben"><button class="icon-btn dark" type="submit" aria-label="Kommentar senden">${icon('send',18)}</button></form></section></div>`;
modal('Details',content,{wide:true,cls:'detail-modal',footer:`<div class="detail-footer-copy"><strong>${activity?(expired?'Aktivität beendet':full(p)?'Alle Plätze belegt':'${FREE}'):p.status==='reserved'?'Bereits reserviert':p.price?`${p.price} €`:'Kostenlos'}</strong><span>${e(p.location)}</span></div><button class="btn primary" data-action="${own?'share':activity?'join':'contact'}" data-id="${p.id}" ${expired||full(p)?'disabled':''}>${own?icon('share',17)+' Teilen':activity?(joined(p.id)?icon('check',17)+' Du bist dabei':'Bin dabei'):(p.type==='help'?'Nachricht schreiben':'Kontakt aufnehmen')}</button>`.replace('${FREE}',p.price?`${p.price} €`:'Kostenlos')});
loadComments(id);
}
async function loadComments(id) { try { const comments = isDemo()?(state.comments[id]||[]):await api.comments(id);if(state.selected!==id)return;$('#comments-list').innerHTML=comments.length?comments.map(c=>`<div class="comment">${avatar(isDemo()?demoPerson(demoWorld,c.author_id||c.author?.id):c.author||state.user,'mini')}<div><strong>${e(isDemo()?demoPerson(demoWorld,c.author_id||c.author?.id).name:c.author?.name||state.user.name)} <small>${relative(c.created_at)}</small></strong><p>${e(c.body)}</p></div></div>`).join(''):'<p class="muted">Noch keine Kommentare.</p>';$('#comment-count').textContent=comments.length||'';}catch{if($('#comments-list'))$('#comments-list').innerHTML='<p class="muted">Kommentare konnten nicht geladen werden.</p>';} }
function createModal(type=state.createType,editingId=null,ride=false) { state.overlay='create';state.createType=type;state.editingId=editingId;state.postPhotoDraft=null;const editing=state.posts.find(p=>p.id===editingId);const draft=editing?{...editing,date:editing.starts_at?new Date(new Date(editing.starts_at).getTime()-new Date(editing.starts_at).getTimezoneOffset()*60000).toISOString().slice(0,10):'',time:editing.starts_at?timeLabel(editing.starts_at):''}:readLocal('fhv-draft',{});if(ride)draft.category='Mitfahren';if(!draft.category)draft.category=type==='help'?'Lernen':type==='food'?'Food':'Campus';const title=type==='activity'?'Aktivität':type==='help'?'Hilfe & Nachhilfe':TYPES[type];const tomorrow=new Date(Date.now()+86400000); const date=new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,10);modal(editing?'Beitrag bearbeiten':'Etwas starten',`<div class="create-intro"><h2>${title}</h2></div><div class="create-types">${Object.entries(TYPES).map(([key,label])=>`<button type="button" class="type-option ${state.createType===key?'selected':''}" data-action="create-type" data-value="${key}" ${editing?'disabled':''}>${icon({activity:'calendar',trade:'trade',food:'leaf',help:'book',life:'people'}[key],18)} ${label}</button>`).join('')}<button type="button" class="type-option ${draft.category==='Mitfahren'?'selected':''}" data-action="create-ride" ${editing?'disabled':''}>${icon('car',18)} Fahrgemeinschaft</button></div><form id="create-form"><input type="hidden" name="type" value="${type}"><label>Titel<input name="title" required minlength="4" maxlength="100" value="${e(draft.type===type?draft.title||'':'')}" placeholder="${({activity:'Zum Beispiel: Morgen zusammen bouldern?',trade:'Zum Beispiel: Skier, 170 cm, 45 €',food:'Zum Beispiel: Eine Portion Pasta zu viel',help:'Zum Beispiel: Hilfe bei Technischer Mechanik',life:'Was möchtest du mit dem Campus teilen?'})[type]}"></label><label>Beschreibung<textarea name="description" required minlength="10" maxlength="3000" rows="4" placeholder="Was sollten andere wissen?">${e(draft.type===type?draft.description||'':'')}</textarea></label>${imageEditor('post',draft.image_data)}${type==='activity'?`<div class="form-row"><label>Datum<input type="date" name="date" min="${date}" value="${draft.type===type&&draft.date>=date?draft.date:date}" required></label><label>Uhrzeit<input type="time" name="time" value="${e(draft.type===type?draft.time||'18:00':'18:00')}" required></label></div>`:''}<label>${type==='activity'?'Treffpunkt':'Übergabe / Ort'}<input name="location" list="campus-spots" maxlength="150" required placeholder="Wähle einen Campus-Spot oder eigenen Ort" value="${e(draft.type===type?draft.location||'':'')}"><datalist id="campus-spots">${SPOTS.map(s=>`<option value="${s.name} · FHV">`).join('')}<option value="Nach Vereinbarung"></datalist></label>${type==='activity'?`<div id="ride-fields" ${draft.category==='Mitfahren'?'':'hidden'}><label>Ziel<input name="ride_destination" maxlength="150" value="${e(draft.ride_destination||'')}" placeholder="Zum Beispiel: Bregenz Bahnhof" ${draft.category==='Mitfahren'?'required':'disabled'}></label><label>Kostenbeitrag pro Person in €<input name="price" type="number" min="0" max="10000" step="0.01" value="${Number(draft.price||0)}" ${draft.category==='Mitfahren'?'':'disabled'}></label></div>`:''}<div class="form-row"><label>Kategorie<select name="category">${CATEGORIES.filter(x=>x!=='Alle'&&(type==='activity'||x!=='Mitfahren')).map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${type==='activity'?`<label>${draft.category==='Mitfahren'?'Freie Plätze':'Max. Personen'}<input type="number" name="capacity" min="${draft.category==='Mitfahren'?1:2}" max="${draft.category==='Mitfahren'?8:500}" placeholder="Offen für alle" value="${e(draft.capacity||'')}"></label>`:type==='trade'||type==='help'?`<label>Preis in € · 0 = verschenken<input type="number" name="price" min="0" max="10000" step="0.01" value="${Number(draft.price||0)}"></label>`:''}</div>${type==='help'?'<label>Du möchtest …<select name="help_direction"><option value="offer">Hilfe anbieten</option><option value="request">Um Hilfe bitten</option></select></label>':''}${type==='food'?'<div class="info-box">'+icon('leaf',20)+'<p>Bitte Zutaten und Allergene in der Beschreibung nennen. Persönliche Übergabe vereinbaren.</p></div>':''}${isOh()?'<label class="check-label"><input type="checkbox" name="pinned"> Als ÖH veröffentlichen und oben im Feed anpinnen</label>':''}<div class="form-error" id="create-error" role="alert"></div><div class="publishing-as">${avatar(state.user,'mini')}<span>Als <strong>${e(state.user.name)}</strong><small>${isDemo()?'Demo · auf diesem Gerät':'Für die FHV Community'}</small></span><button class="text-link" type="button" data-action="save-draft">Entwurf speichern</button></div><button type="submit" class="btn primary full">${icon('plus',18)} ${editing?'Änderungen speichern':isDemo()?'In der Demo veröffentlichen':'Veröffentlichen'}</button></form>`,{wide:true,cls:'create-modal'});state.postPhotoDraft=draft.image_data||null;if(editing){const help=$('[name=help_direction]');if(help)help.value=editing.help_direction||'offer';const pin=$('[name=pinned]');if(pin)pin.checked=editing.pinned;} }
function authModal(mode='login') { state.overlay='auth';state.authMode=mode;modal('',`<div class="auth-brand">${logo}</div><h2>${mode==='signup'?'Konto erstellen':'Anmelden'}</h2><p>Nur mit bestätigter FHV-Mailadresse.</p><div class="segment-control"><button class="${mode==='login'?'selected':''}" data-action="auth-mode" data-value="login">Anmelden</button><button class="${mode==='signup'?'selected':''}" data-action="auth-mode" data-value="signup">Konto erstellen</button></div><form id="auth-form">${mode==='signup'?'<label>Dein Name<input name="name" autocomplete="name" placeholder="Wie heißt du?" required minlength="2" maxlength="80"></label>':''}<label>FHV-Mailadresse<input type="email" name="email" autocomplete="email" placeholder="vorname.nachname@students.fhv.at" required></label><label>Passwort<input name="password" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="${mode==='signup'?12:1}" required placeholder="${mode==='signup'?'Mindestens 12 Zeichen':'Dein Passwort'}"></label>${mode==='signup'?'<p class="form-hint">Du erhältst eine Bestätigungsmail. Erst danach kannst du dich anmelden.</p>':''}<div class="form-error" id="auth-error" role="alert"></div>${!configured?'<div class="setup-notice">'+icon('settings',20)+'<span><strong>Live-Anmeldung noch nicht freigeschaltet.</strong> Die App ist vorbereitet. Datenbank und Mailversand müssen noch verbunden werden.</span></div>':''}<button class="btn primary full" type="submit" ${!configured?'disabled':''}>${mode==='signup'?'Konto erstellen':'Mit FHV-Mail anmelden'}</button></form>${mode==='login'?'<button class="text-link auth-demo" data-action="recover">Passwort vergessen?</button>':''}<div class="auth-secure">${icon('shield',15)} @students.fhv.at & @fhv.at · Mailbestätigung erforderlich</div><button class="text-link auth-demo" data-action="close">Demo öffnen</button>`,{cls:'auth-modal'}); }
function editProfile(){state.overlay='edit-profile';state.profilePhotoDraft=state.user.avatar_data||null;modal('Profil bearbeiten',`<form id="profile-form">${imageEditor('profile',state.user.avatar_data)}<label>Name<input name="name" value="${e(state.user.name)}" required minlength="2" maxlength="80"></label><label>Studiengang<input name="course" value="${e(state.user.course||'')}" placeholder="z. B. Mechatronik · Master" maxlength="100"></label><label>Über mich<textarea name="bio" maxlength="400" rows="3" placeholder="Interessen, Semester, was ihr gern macht …">${e(state.user.bio||'')}</textarea></label><label>Interessen<input name="interests" maxlength="200" value="${e((state.user.interests||[]).join(', '))}" placeholder="Bouldern, Radfahren, Musik"></label><div class="form-error" id="profile-error" role="alert"></div><button type="submit" class="btn primary full">Speichern</button></form>`);}
function notifications() { state.noticeRead=true;render();state.overlay='notifications';modal('Für dich auf dem Campus',`<p class="modal-lead"></p><div class="notification-list">${pendingInvites().length?pendingInvites().map(invitationCard).join(''):empty('Du bist auf dem neuesten Stand.','Neue Einladungen findest du hier.',null)}</div>`); }
function savedModal(own=false) { state.overlay=own?'my-posts':'saved';const posts=state.posts.filter(p=>own?p.author_id===state.user.id:state.saved.includes(p.id));modal(own?'Deine Beiträge':'Für später gemerkt',`<div class="saved-list">${posts.length?posts.map(p=>`<button class="saved-row" data-action="detail" data-id="${p.id}"><span class="saved-thumb">${safeImage(p.image_data)?`<img src="${e(safeImage(p.image_data))}" alt="">`:icon('calendar',24)}</span><span><small>${e(TYPES[p.type])}</small><strong>${e(p.subtitle||p.title)}</strong><small>${e(p.location)}</small></span>${icon('chevron',17)}</button>`).join(''):empty(own?'Noch keine Beiträge.':'Noch nichts gemerkt.','',own?'create':'close',own?'Etwas starten':'Campus entdecken')}</div>`); }
function about() { state.overlay='about';modal('FHV Friends',`<div class="about-brand">${logo}</div><p>Eine studentische Campus-App für die FHV in Dornbirn. Aktivitäten, Dinge und Wissen teilen — und dabei neue Leute kennenlernen.</p><div class="info-box blue">${icon('people',25)}<div><strong>Ein gutes Miteinander.</strong><p>Sei respektvoll. Halte Absprachen ein. Teile keine privaten Daten anderer Personen. Triff dich für Übergaben an einem öffentlichen Ort.</p></div></div><h3>Deine Privatsphäre</h3><p>Im Livebetrieb sind Beiträge und Profile nur für bestätigte FHV-Konten sichtbar. Direktnachrichten können nur die beteiligten Personen lesen. Deine Mailadresse wird nicht im Profil angezeigt. Es gibt keine Werbetracker.</p><h3>Aktueller Stand</h3><p>${isDemo()?'Du nutzt die Demo mit fiktiven Personen und Beispieldaten. Eingaben bleiben im Browser dieses Geräts. Es werden keine Nachrichten an echte Personen verschickt.':'Du nutzt die Live-App. Deine Inhalte werden in der verbundenen Supabase-Datenbank gespeichert.'}</p><h3>Transparenz</h3><p>Studentischer Prototyp. Die FHV-Bildmarke ist Eigentum der FH Vorarlberg. Der Prototyp ist kein offizieller Dienst der Hochschule. Verantwortliche Stelle, Impressum und abschließende Datenschutzhinweise werden vor dem Start mit echten Nutzerdaten ergänzt.</p>${isDemo()?'<button class="btn outline full" data-action="reset-demo">Demo auf diesem Gerät zurücksetzen</button>':''}`); }
async function toggleSave(id) { const on=!state.saved.includes(id); if(!isDemo())await api.toggle('bookmarks',id,state.user.id,on); state.saved=on?[...state.saved,id]:state.saved.filter(x=>x!==id);persist();render();if(state.overlay==='detail')detail(id);toast(on?'Für später gemerkt.':'Aus deiner Merkliste entfernt.'); }
async function toggleLike(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;const on=!state.liked.includes(id);if(!isDemo())await api.toggle('likes',id,state.user.id,on);state.liked=on?[...state.liked,id]:state.liked.filter(x=>x!==id);p.likes=Math.max(0,Number(p.likes||0)+(on?1:-1));persist();render(); }
async function joinActivity(id) { const p=state.posts.find(x=>x.id===id);if(!p||p.type!=='activity')return;const on=!joined(id);if(on&&full(p)){toast('Alle Plätze sind schon belegt.');return;}if(!isDemo())await api.rpc('set_attendance',{activity_id:id,attending:on});state.joined=on?[...state.joined,id]:state.joined.filter(x=>x!==id);p.join_count=Math.max(0,count(p)+(on?1:-1));persist();render();if(state.overlay==='detail')detail(id);toast(on?'Du bist dabei.':'Du hast dich abgemeldet.'); }
async function respondInvite(id,status) { const inv=state.invitations.find(x=>x.id===id);if(!inv)return;const p=state.posts.find(x=>x.id===inv.post_id);if(status==='accepted'&&p&&full(p)){toast('Diese Aktivität ist inzwischen ausgebucht.');return;}if(!isDemo())await api.invitationStatus(id,status);if(status==='accepted'&&!joined(inv.post_id)){state.joined.push(inv.post_id);if(p)p.join_count=count(p)+1;}inv.status=status;persist();render();if(state.overlay==='notifications')notifications();toast(status==='accepted'?'Einladung angenommen.':'Einladung abgelehnt.'); }
async function contact(id){const p=state.posts.find(x=>x.id===id);if(p)await messagePerson(p.author_id);}
async function messagePerson(id){
 if(id===state.user.id)return toast('Das ist dein eigenes Profil.');
 if(!isDemo())return openChat(await api.rpc('start_direct_chat',{other_user:id}));
 const person=demoPerson(demoWorld,id);let chat=state.chats.find(c=>!c.post_id&&c.members?.includes(state.user.id)&&c.members?.includes(id));
 if(!chat){chat={id:crypto.randomUUID(),members:[state.user.id,id],title:person.name,created_at:new Date().toISOString()};state.chats.push(chat);state.messages[chat.id]=[];persist();}return openChat(chat.id);
}
let connectionRows=[],peopleRows=[];
async function loadPeople(){peopleRows=isDemo()?demoWorld.profiles:await api.people();connectionRows=isDemo()?(demoWorld.connections??=[]):await api.connections();}
const connectionWith=id=>connectionRows.find(c=>(c.sender_id===state.user.id&&c.recipient_id===id)||(c.recipient_id===state.user.id&&c.sender_id===id));
async function people(){
 state.overlay='people';await loadPeople();modal('Kontakte',`<div class="people-tabs">${['Alle','Verbunden','Anfragen'].map(v=>`<button class="chip ${state.peopleTab===v?'selected':''}" data-action="people-filter" data-value="${v}">${v}</button>`).join('')}</div><div class="chat-list">${peopleRows.filter(p=>p.id!==state.user.id).filter(p=>{const c=connectionWith(p.id);return state.peopleTab==='Verbunden'?c?.status==='accepted':state.peopleTab==='Anfragen'?c?.status==='pending'&&c.recipient_id===state.user.id:true;}).map(p=>{const c=connectionWith(p.id);return `<button class="chat-row" data-action="person" data-id="${p.id}">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(c?.status==='accepted'?'Verbunden':c?.status==='pending'?(c.recipient_id===state.user.id?'Möchte sich verbinden':'Anfrage gesendet'):p.course||'FHV')}</small></span>${icon('chevron',18)}</button>`;}).join('')||'<p class="muted">Hier ist es noch leer.</p>'}</div>`);
}
async function personProfile(id){
 if(id===state.user.id){closeModal();return navigate('profile');}await loadPeople();const p=peopleRows.find(p=>p.id===id)||(isDemo()?demoPerson(demoWorld,id):await api.profile(id));if(!p)return;state.overlay='person';const c=connectionWith(id);modal(p.name,`<div class="person-profile">${avatar(p,'large')}<h2>${e(p.name)}</h2><p class="muted">${e(p.course||'FHV')}</p>${p.bio?`<p>${e(p.bio)}</p>`:''}<div class="interest-chips">${(p.interests||[]).map(x=>`<span>${e(x)}</span>`).join('')}</div></div><div class="person-actions"><button class="btn primary" data-action="message-person" data-id="${id}">${icon('chat',18)} Nachricht</button>${c?.status==='accepted'?`<button class="btn outline" data-action="disconnect" data-id="${id}">Verbunden · entfernen</button>`:c?.status==='pending'?(c.recipient_id===state.user.id?`<button class="btn soft" data-action="connect-accept" data-id="${id}">Annehmen</button><button class="btn outline" data-action="disconnect" data-id="${id}">Ablehnen</button>`:`<button class="btn outline" data-action="disconnect" data-id="${id}">Anfrage zurückziehen</button>`):`<button class="btn soft" data-action="connect" data-id="${id}">Verbinden</button>`}</div><div class="section-heading"><h2>Beiträge</h2></div><div class="post-grid">${state.posts.filter(x=>x.author_id===id).map(x=>postCard(x)).join('')||'<p class="muted">Noch keine Beiträge.</p>'}</div>`);
}
async function changeConnection(id,action){
 await loadPeople();const c=connectionWith(id);
 if(isDemo()){
  if(action==='request'&&!c)demoWorld.connections.push({id:crypto.randomUUID(),sender_id:state.user.id,recipient_id:id,status:'pending'});
  if(action==='accept'&&c?.recipient_id===state.user.id)c.status='accepted';
  if(action==='remove'&&c)demoWorld.connections=demoWorld.connections.filter(x=>x.id!==c.id);persist();
 }else if(action==='request')await api.connect(id);else if(action==='accept'&&c)await api.respondConnection(c.id,true);else if(c)await api.disconnect(c.id);
 await personProfile(id);
}
const franziConversations=new Map();let franziBusy=false,franziStatus='',franziLoading=false;
const franziHistory=()=>{if(!franziConversations.has(state.user.id))franziConversations.set(state.user.id,[]);return franziConversations.get(state.user.id);};
function franzi(){state.overlay='franzi';const history=franziHistory();modal('Franzi',`<div class="franzi-intro"><span class="franzi-avatar">${icon('franzi',33)}</span><div><strong>Frag mich.</strong><p>${franziReady()?'KI läuft auf deinem Gerät.':'Campus-Hilfe · KI optional aktivieren'}</p></div></div>${!franziReady()?`<div class="franzi-setup"><p>Für allgemeine Fragen: kostenlose KI auf deinem Gerät. Einmaliger Download von etwa 1 GB, kein API-Schlüssel. Benötigt WebGPU.</p><button class="btn soft full" data-action="franzi-start" ${franziLoading?'disabled':''}>${franziLoading?'KI wird geladen …':'Lokale KI aktivieren'}</button><small role="status">${e(franziStatus)}</small></div>`:''}<div class="franzi-messages" aria-live="polite">${history.map(m=>`<div class="franzi-message ${m.role}"><strong>${m.role==='user'?'Du':'Franzi'}</strong><p>${e(m.content)}</p></div>`).join('')||'<p class="muted">Wie verkaufe ich etwas? Wie finde ich Leute?</p>'}${franziBusy?'<p class="muted">Franzi überlegt …</p>':''}</div><form id="franzi-form"><label class="sr-only" for="franzi-question">Deine Frage</label><div class="message-compose"><input id="franzi-question" name="question" placeholder="Frag Franzi …" maxlength="1000" required ${franziBusy?'disabled':''}><button class="btn primary" type="submit" ${franziBusy?'disabled':''}>${icon('send',18)}<span class="sr-only">Senden</span></button></div></form><p class="form-hint">${franziReady()?'KI kann sich irren. Kein Zugriff auf private Chats oder Live-Informationen.':'Ohne KI kann ich Fragen zu FHV Friends beantworten.'}</p>`);const list=$('.franzi-messages');if(list)list.scrollTop=list.scrollHeight;if(!franziBusy)$('#franzi-question')?.focus();}
async function activateFranzi(){if(franziLoading)return;franziLoading=true;franziStatus='Download wird vorbereitet …';franzi();try{await startFranziAI(status=>{franziStatus=status;const target=document.querySelector('.franzi-setup small');if(target)target.textContent=status;});franziStatus='';}catch(error){franziStatus=error.message;}finally{franziLoading=false;if(state.overlay==='franzi')franzi();}}
async function askFranzi(question){const history=franziHistory();if(franziBusy)return;franziBusy=true;history.push({role:'user',content:question});franzi();try{const answer=franziReady()?await franziAnswer(history,state.posts):campusAnswer(question,state.posts);history.push({role:'assistant',content:answer});}catch{history.push({role:'assistant',content:'Die KI hat gerade nicht geantwortet. Versuch es bitte erneut.'});}finally{franziBusy=false;if(state.overlay==='franzi')franzi();}}

async function inbox() { state.overlay='inbox';if(!isDemo())state.chats=await api.chats();const chats=isDemo()?visibleDemoChats(state.chats,state.user.id,state.joined,state.posts):state.chats;modal('Nachrichten',`<button class="btn outline full" data-action="people">${icon('plus',18)} Neue Nachricht</button>${isDemo()?'<div class="inline-demo">Demo · auf diesem Gerät.</div>':''}<div class="chat-list">${chats.length?chats.map(c=>{const messages=state.messages[c.id]||[];return `<button class="chat-row" data-action="chat" data-id="${c.id}">${avatar(isDemo()?demoPerson(demoWorld,c.members?.find(id=>id!==state.user.id)):({name:c.title,color:'blue'}))}<span><strong>${e(chatTitle(c))}</strong><small>${e(messages.at(-1)?.body||'Noch keine Nachrichten')}</small></span>${icon('chevron',18)}</button>`;}).join(''):empty('Noch keine Nachrichten.','Wähle unter Kontakte eine Person aus.',null)}</div>`); }
async function openChat(id) { if(!isDemo()&&!state.chats.find(c=>c.id===id))state.chats=await api.chats();const chat=state.chats.find(c=>c.id===id);if(isDemo()&&!visibleDemoChats(state.chats,state.user.id,state.joined,state.posts).some(c=>c.id===id)){toast('Dieser Testchat gehört zu einem anderen Profil.');return;}state.currentChat=id;state.overlay='chat';modal(chatTitle(chat),`<button class="text-link chat-back" data-action="inbox">${icon('chevron',20,'back-icon')} Nachrichten</button>${isDemo()?'<div class="inline-demo">Testchat · nur auf diesem Gerät.</div>':''}<div class="chat-messages" id="chat-messages" aria-live="polite"></div><form id="message-form" class="message-form"><input name="body" required maxlength="2000" aria-label="Nachricht" autocomplete="off" placeholder="Nachricht …"><button class="icon-btn dark" type="submit" aria-label="Nachricht senden">${icon('send',20)}</button></form>`,{cls:'chat-modal'});await loadMessages(id);if(!isDemo())chatInterval=setInterval(()=>loadMessages(id),8000); }
async function loadMessages(id) { if(state.currentChat!==id)return;try{const messages=isDemo()?(state.messages[id]||[]):await api.messages(id);if(state.currentChat!==id)return;state.messages[id]=messages;const list=$('#chat-messages');if(!list)return;const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<80;list.innerHTML=messages.length?messages.map(m=>`<div class="message ${m.author_id===state.user.id?'mine':''}"><p>${e(m.body)}</p><small>${e(isDemo()?demoPerson(demoWorld,m.author_id).name:m.author?.name||state.user.name)} · ${timeLabel(m.created_at)}</small></div>`).join(''):'<div class="chat-empty">'+icon('chat',42)+'<h3>Noch keine Nachrichten.</h3><p></p></div>';if(nearBottom)list.scrollTop=list.scrollHeight;}catch{toast('Nachrichten konnten nicht geladen werden.');} }
async function groupChat(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;if(isDemo()&&!joined(id)&&p.author_id!==state.user.id){toast('Tritt zuerst der Aktivität bei.');return;}if(!isDemo()){const chat=await api.rpc('activity_chat',{activity_id:id});return openChat(chat);}let chat=state.chats.find(c=>c.post_id===id);if(!chat){chat={id:crypto.randomUUID(),post_id:id,title:p.subtitle||p.title,created_at:new Date().toISOString(),color:'yellow'};state.chats.push(chat);state.messages[chat.id]=[];persist();}openChat(chat.id); }
function install(){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>deferredInstall=null);return;}modal('App installieren',`<p>FHV Friends lässt sich auf dem Homescreen ablegen und ohne Browserleiste öffnen.</p><div class="install-step"><strong>iPhone / iPad</strong><p>In Safari: Teilen → Zum Home-Bildschirm.</p></div><div class="install-step"><strong>Android</strong><p>In Chrome: Menü → App installieren. Alternativ gibt es den Android-Wrapper als Test-APK.</p><a class="text-link" href="https://github.com/konstantinmantel/fhv-friends/actions/workflows/android.yml" target="_blank" rel="noopener noreferrer">Android-Download auf GitHub</a></div><div class="install-step"><strong>Computer</strong><p>In Chrome oder Edge das Installationssymbol in der Adressleiste wählen.</p></div>`);}

function postMenu(id) {const p=state.posts.find(x=>x.id===id);if(!p)return;const own=p.author_id===state.user.id;state.selected=id;state.overlay='post-menu';modal('Zum Beitrag',`<div class="action-list"><button data-action="share" data-id="${id}">${icon('share')} Beitrag teilen</button><button data-action="save" data-id="${id}">${icon('bookmark')} ${state.saved.includes(id)?'Nicht mehr merken':'Für später merken'}</button>${isOh()?`<button data-action="pin" data-id="${id}">${icon('pin')} ${p.pinned?'Nicht mehr anpinnen':'Oben im Feed anpinnen'}</button>`:''}${own?`<button data-action="edit-post" data-id="${id}">${icon('settings')} Beitrag bearbeiten</button><button class="danger" data-action="confirm-delete" data-id="${id}">${icon('trash')} Beitrag löschen</button>`:`<button data-action="report" data-id="${id}">${icon('flag')} Beitrag melden</button>`}</div>`); }
async function share(id) { const p=state.posts.find(x=>x.id===id);const url=new URL(location.href);url.hash=`post/${id}`; if(navigator.share){try{await navigator.share({title:p?.title||'FHV Friends',text:'Bist du dabei? Auf FHV Friends.',url:url.href});}catch(ex){if(ex.name!=='AbortError')toast('Teilen ist gerade nicht verfügbar.');}}else{try{await navigator.clipboard.writeText(url.href);toast('Link kopiert. Jetzt jemanden mitnehmen!');}catch{modal('Beitrag teilen',`<label>Link zum Kopieren<input readonly value="${e(url.href)}"></label>`);}} }
function calendar(id) { const p=state.posts.find(x=>x.id===id);if(!p?.starts_at)return;const url=URL.createObjectURL(new Blob([makeICS(p)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fhv-friends.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Kalendereintrag heruntergeladen.'); }
async function loadLive(user) { state.loading=true;state.mode='live';render();try { const [profile,role,posts,userState,memberships]=await Promise.all([api.profile(user.id),api.role(),api.posts(),api.state(user.id),api.memberships()]);state.user={...profile,id:user.id,role};state.posts=posts.map(p=>({...p,price:Number(p.price||0),likes:Number(p.likes||0)}));Object.assign(state,userState);const counts={};memberships.forEach(m=>counts[m.post_id]=(counts[m.post_id]||0)+1);state.posts.forEach(p=>p.join_count=counts[p.id]||0); }catch(error){state.posts=[];toast(error.message);}finally{state.loading=false;render();} }
async function invitePeople(id) { state.overlay='invite-people';const people=isDemo()?demoWorld.profiles:await api.people();modal('Leute einladen',`<p class="modal-lead"></p><div class="people-list">${people.filter(p=>p.id!==state.user.id).map(p=>`<div class="people-row">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(p.course||'FHV Community')}</small></span><button class="btn soft small" data-action="send-invite" data-post="${id}" data-id="${p.id}">Einladen</button></div>`).join('')}</div>${isDemo()?'<div class="inline-demo">Demo · Es werden keine echten Einladungen verschickt.</div>':''}`); }
function imageEditor(kind,data){return `<div class="photo-editor"><div id="${kind}-photo-preview" class="photo-preview ${kind==='profile'?'round':''}">${safeImage(data)?`<img src="${e(safeImage(data))}" alt="Ausgewähltes Foto">`:icon(kind==='profile'?'user':'plus',26)}</div><div><label class="photo-label">${kind==='profile'?'Profilfoto':'Foto (optional)'}<input id="${kind}-photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="text-link photo-remove" type="button" data-action="remove-photo" data-kind="${kind}">Foto entfernen</button><small>JPG, PNG oder WebP · maximal 8 MB</small></div></div>`;}
function removePhoto(kind){if(kind==='profile')state.profilePhotoDraft=null;else state.postPhotoDraft=null;const box=$(`#${kind}-photo-preview`);if(box)box.innerHTML=icon(kind==='profile'?'user':'plus',26);const file=$(`#${kind}-photo`);if(file)file.value='';}
async function preparePhoto(file,maxLength){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Bitte ein JPG-, PNG- oder WebP-Foto wählen.');
 if(file.size>8*1024*1024)throw new Error('Das Foto darf maximal 8 MB groß sein.');
 const url=URL.createObjectURL(file);
 try{
  const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Das Foto konnte nicht geöffnet werden.'));i.src=url;});
  const canvas=document.createElement('canvas');let edge=maxLength<=120000?384:960;
  for(let attempt=0;attempt<5;attempt++){
   const ratio=Math.min(1,edge/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));
   const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);
   const value=canvas.toDataURL('image/jpeg',.78-attempt*.08);if(safeImage(value,maxLength))return value;edge=Math.round(edge*.8);
  }
  throw new Error('Bitte ein kleineres Foto wählen.');
 }finally{URL.revokeObjectURL(url);}
}
function testAccounts(){if(!isDemo())return;state.overlay='test-accounts';modal('Testprofile',`<p class="modal-lead">Name, Foto und Beschreibung könnt ihr selbst ergänzen.</p><div class="test-accounts">${demoWorld.profiles.map((p,i)=>`<button class="test-account ${p.id===state.user.id?'current':''}" data-action="switch-account" data-id="${p.id}">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(p.course||`Testprofil ${i+1}`)}</small></span>${p.id===state.user.id?icon('check',18):icon('chevron',18)}</button>`).join('')}</div><p class="form-hint">Diese vier Demo-Profile teilen Beiträge und Chats auf diesem Gerät. Keine echten FHV-Anmeldungen.</p>`);}
function switchAccount(id){
 if(!isDemo()||!demoWorld.profiles.some(p=>p.id===id))return;
 persist();const account=demoWorld.accounts[id]||emptyDemoAccount();state.user={...demoPerson(demoWorld,id)};
 Object.assign(state,{joined:account.joined,saved:account.saved,liked:account.liked,invitations:account.invitations});
 state.posts=hydrateDemoPosts(demoWorld);try{sessionStorage.setItem('fhv-demo-active',id);}catch{}
 closeModal();render();toast(`${state.user.name} ausgewählt.`);
}
function chatTitle(chat){if(!chat)return 'Nachrichten';if(!isDemo()||chat.post_id)return chat.title||'Gruppenchat';const other=chat.members?.find(id=>id!==state.user.id);return other?demoPerson(demoWorld,other).name:chat.title||'Chat';}

const actions = {
 nav:el=>navigate(el.dataset.tab),close:closeModal,backdrop:el=>{if(el===eventTarget)closeModal();},
 filter:el=>{state.filter=el.dataset.value;render();},
 'activity-tab':el=>{state.activityTab=el.dataset.value;state.filter='Alle';state.query='';render();},
 'trade-tab':el=>{state.tradeTab=el.dataset.value;state.filter='Alle';state.query='';render();},
 detail:el=>detail(el.dataset.id),create:()=>createModal(),'create-trade':()=>createModal('trade'),'create-ride':()=>{saveDraft(false);createModal('activity',null,true);},
 rides:()=>{navigate('activities');state.filter='Mitfahren';render();},market:()=>navigate('trade'),people,person:el=>personProfile(el.dataset.id),'people-filter':el=>{state.peopleTab=el.dataset.value;return people();},'message-person':el=>messagePerson(el.dataset.id),connect:el=>changeConnection(el.dataset.id,'request'),'connect-accept':el=>changeConnection(el.dataset.id,'accept'),disconnect:el=>changeConnection(el.dataset.id,'remove'),franzi,'franzi-start':activateFranzi,
 'create-type':el=>{saveDraft(false);createModal(el.dataset.value);},
 'save-draft':()=>saveDraft(true),auth:()=>authModal(),
 'auth-mode':el=>authModal(el.dataset.value),recover:()=>{state.overlay='recover';modal('Passwort zurücksetzen',`<p>Wir schicken dir einen Link an deine FHV-Mailadresse.</p><form id="recovery-form"><label>FHV-Mailadresse<input name="email" type="email" autocomplete="email" required placeholder="name@students.fhv.at"></label><div class="form-error" id="recovery-error" role="alert"></div><button class="btn primary full" type="submit" ${!configured?'disabled':''}>Link anfordern</button></form>`);},
 'edit-profile':editProfile,'test-accounts':testAccounts,'switch-account':el=>switchAccount(el.dataset.id),'remove-photo':el=>removePhoto(el.dataset.kind),saved:()=>savedModal(), 'my-posts':()=>savedModal(true),
 help:()=>{navigate('trade');state.filter='Hilfe';render();},
 discover:()=>{navigate('activities');state.activityTab='Entdecken';render();},
 save:el=>toggleSave(el.dataset.id),like:el=>toggleLike(el.dataset.id),join:el=>joinActivity(el.dataset.id),
 accept:el=>respondInvite(el.dataset.id,'accepted'),decline:el=>respondInvite(el.dataset.id,'declined'),
 'post-menu':el=>postMenu(el.dataset.id),'edit-post':el=>{const p=state.posts.find(x=>x.id===el.dataset.id);if(p)createModal(p.type,p.id);},notifications,inbox,chat:el=>openChat(el.dataset.id),
 contact:el=>contact(el.dataset.id),'group-chat':el=>groupChat(el.dataset.id),
 share:el=>share(el.dataset.id),calendar:el=>calendar(el.dataset.id),install,about,
 'invite-people':el=>invitePeople(el.dataset.id),
 'send-invite':async el=>{if(!isDemo())await api.invitations(el.dataset.post,el.dataset.id,state.user.id);else{const recipient=demoWorld.accounts[el.dataset.id]||emptyDemoAccount();if(!recipient.invitations.some(i=>i.post_id===el.dataset.post))recipient.invitations.push({id:crypto.randomUUID(),post_id:el.dataset.post,sender_id:state.user.id,status:'pending'});demoWorld.accounts[el.dataset.id]=recipient;persist();}el.disabled=true;el.textContent='Eingeladen';toast(isDemo()?'Einladung in der Demo vorgemerkt.':'Einladung verschickt.');},
 'confirm-delete':el=>modal('Beitrag löschen?',`<p>Dein Beitrag und zugehörige Zusagen und Kommentare werden gelöscht.</p><button class="btn primary full" data-action="delete" data-id="${el.dataset.id}">Beitrag löschen</button>`),
 delete:async el=>{const id=el.dataset.id;if(!isDemo())await api.deletePost(id);state.posts=state.posts.filter(p=>p.id!==id);state.joined=state.joined.filter(x=>x!==id);state.saved=state.saved.filter(x=>x!==id);persist();closeModal();render();toast('Beitrag gelöscht.');},
 pin:async el=>{const p=state.posts.find(p=>p.id===el.dataset.id);if(!isOh()||!p)return;if(!isDemo())await api.pinPost(p.id,!p.pinned);p.pinned=!p.pinned;persist();closeModal();render();toast(p.pinned?'Oben im Feed angepinnt.':'Beitrag nicht mehr angepinnt.');},
 report:el=>modal('Beitrag melden',`<p>Hilf uns, den Campus respektvoll zu halten.</p><form id="report-form" data-id="${el.dataset.id}"><label>Was ist los?<select name="reason"><option>Unangemessener Inhalt</option><option>Spam oder Werbung</option><option>Irreführendes Angebot</option><option>Belästigung</option><option>Sonstiges</option></select></label><button class="btn primary full" type="submit">${isDemo()?'Meldung in Demo testen':'Meldung abschicken'}</button></form>`),
 'reset-demo':()=>modal('Demo zurücksetzen?',`<p>Deine lokalen Demo-Beiträge, Nachrichten und Profiländerungen werden entfernt.</p><button class="btn primary full" data-action="reset-confirm">Demo zurücksetzen</button>`),
 'reset-confirm':()=>{localStorage.removeItem('fhv-demo-v1');localStorage.removeItem('fhv-demo-v2');localStorage.removeItem('fhv-draft');location.href=location.pathname;},
 logout:async()=>{await api.logout();state.mode='demo';Object.assign(state,{user:{...DEMO_USER},posts:demoPosts(),joined:['hike'],saved:[],liked:[],comments:{},chats:[],messages:{},invitations:[]});closeModal();navigate('feed');toast('Du bist abgemeldet.');},
};
let eventTarget;
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(!actions[action])return;
 eventTarget=event.target;if(action==='backdrop'&&event.target!==el)return;
 if(el.dataset.pending)return;el.dataset.pending='true';
 try { await actions[action](el); } catch(error) { toast(error.name==='TimeoutError'?'Der Campus braucht gerade etwas länger. Bitte erneut versuchen.':error.message||'Das hat nicht geklappt. Bitte versuche es erneut.'); }
 finally{delete el.dataset.pending;}
});
function saveDraft(show) { const form=$('#create-form');if(!form||state.editingId)return;const draft=Object.fromEntries(new FormData(form));delete draft.photo;draft.image_data=state.postPhotoDraft||null;saveLocal('fhv-draft',draft);if(show)toast('Entwurf auf diesem Gerät gespeichert.'); }
document.addEventListener('input',event=>{
 if(event.target.id==='search'){state.query=event.target.value;const pos=event.target.selectionStart;render();const input=$('#search');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}}
 if(event.target.closest('#create-form')&&event.target.type!=='file')saveDraft(false);
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['create-form','auth-form','profile-form','comment-form','message-form','report-form','recovery-form','password-form','franzi-form'].includes(form.id))return;
 event.preventDefault();if(form.dataset.pending)return;form.dataset.pending='true';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
 const values=Object.fromEntries(new FormData(form));
 try {
  if(form.id==='franzi-form'){if(values.question?.trim())await askFranzi(values.question.trim());}
  else if(form.id==='create-form') {
   const starts_at=values.date&&values.time?new Date(`${values.date}T${values.time}`).toISOString():null;
   const post={type:values.type,title:values.title.trim(),description:values.description.trim(),location:values.location.trim(),category:values.category||'Campus',starts_at,capacity:values.capacity?Number(values.capacity):null,price:Number(values.price||0),help_direction:values.help_direction||null,ride_destination:values.category==='Mitfahren'?values.ride_destination?.trim():null,image_data:state.postPhotoDraft||null,pinned:isOh()&&values.pinned==='on'};
   const error=validatePost(post);if(error)throw new Error(error);
   let result;
   if(!isDemo())result=(state.editingId?await api.updatePost(state.editingId,post):await api.createPost({...post,author_id:state.user.id}))?.[0];
   else result={...post,id:crypto.randomUUID(),author_id:state.user.id,created_at:new Date().toISOString(),status:'open',art:{activity:{Outdoor:'mountain',Sport:'run',Food:'coffee',Lernen:'study',Kultur:'boulder',Campus:'coffee'}[post.category]||'coffee',trade:'lamp',food:'salad',help:'math',life:'study'}[post.type]};
   if(state.editingId){const existing=state.posts.find(p=>p.id===state.editingId);Object.assign(existing,post,result?{...result,id:existing.id}:{});}else state.posts.unshift({...result,author:state.user,join_count:0,likes:0});state.editingId=null;state.overlay=null;localStorage.removeItem('fhv-draft');persist();navigate(post.type==='activity'?'activities':['help','food','trade'].includes(post.type)?'trade':'feed');toast(isDemo()?'Dein Beitrag ist in der Demo veröffentlicht.':'Beitrag veröffentlicht.');
  } else if(form.id==='auth-form') {
   if(state.authMode==='signup') { const data=await api.signup(values.email,values.password,values.name);if(data.session){throw new Error('Bitte E-Mail-Bestätigung im Projekt aktivieren, bevor die App live geht.');}modal('Fast geschafft.',`<div class="auth-mail-icon blue">${icon('mail',38)}</div><h2>Einmal Postfach checken.</h2><p>Falls die Registrierung möglich ist, erhältst du eine Bestätigungsmail an <strong>${e(values.email)}</strong>. Öffne den Link und melde dich danach an.</p><button class="btn primary full" data-action="auth">Zur Anmeldung</button>`); }
   else { const user=await api.login(values.email,values.password);if(!user.email_confirmed_at){await api.logout();throw new Error('Bestätige bitte zuerst deine FHV-Mailadresse.');}closeModal();await loadLive(user);toast('Angemeldet.'); }
  } else if(form.id==='profile-form') {
   const profile={name:values.name.trim(),course:values.course.trim(),bio:values.bio.trim(),interests:values.interests.split(',').map(i=>i.trim()).filter(Boolean).slice(0,8),color:state.user.color||'blue'};
   profile.avatar_data=state.profilePhotoDraft||null;if(!isDemo())await api.saveProfile(state.user.id,profile);Object.assign(state.user,profile);state.posts.forEach(p=>{if(p.author_id===state.user.id)p.author=state.user;});persist();closeModal();render();toast('Dein Profil ist aktualisiert.');
  } else if(form.id==='comment-form') {
   const body=values.body.trim();if(!body)return;const id=form.dataset.post;if(!isDemo())await api.comment(id,state.user.id,body);else{state.comments[id]??=[];state.comments[id].push({id:crypto.randomUUID(),author_id:state.user.id,body,created_at:new Date().toISOString()});persist();}form.reset();await loadComments(id);
  } else if(form.id==='message-form') {
   const body=values.body.trim(),id=state.currentChat;if(!body||!id)return;if(!isDemo())await api.send(id,state.user.id,body);else{state.messages[id]??=[];state.messages[id].push({id:crypto.randomUUID(),author_id:state.user.id,body,created_at:new Date().toISOString()});persist();}form.reset();await loadMessages(id);const list=$('#chat-messages');if(list)list.scrollTop=list.scrollHeight;
  } else if(form.id==='recovery-form') {await api.recover(values.email);modal('Prüfe dein Postfach.',`<p>Falls ein Konto existiert, erhältst du eine E-Mail mit einem Link zum Zurücksetzen.</p><button class="btn primary full" data-action="auth">Zur Anmeldung</button>`);
  } else if(form.id==='password-form') {await api.updatePassword(values.password);closeModal();toast('Dein Passwort ist aktualisiert.');
  } else if(form.id==='report-form') {
   if(!isDemo())await api.report(form.dataset.id,state.user.id,values.reason);closeModal();toast(isDemo()?'Demo-Meldung getestet. Es wurde nichts verschickt.':'Danke. Deine Meldung wird geprüft.');
  }
 } catch(error) {const target=$({ 'create-form':'#create-error','auth-form':'#auth-error','profile-form':'#profile-error','recovery-form':'#recovery-error','password-form':'#password-error'}[form.id]||'#nonexistent');if(target)target.textContent=error.message;else toast(error.message);}
 finally{delete form.dataset.pending;if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){if(state.overlay==='create')saveDraft(false);closeModal();}
 if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)){event.preventDefault();$('#search')?.focus();}
 if(event.key==='Tab'&&$('#overlay .modal')){const nodes=Array.from($('#overlay').querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,select,[tabindex="0"]')).filter(n=>n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;});
window.addEventListener('online',()=>toast('Du bist wieder online.'));
window.addEventListener('offline',()=>toast('Du bist offline. Bereits geladene Inhalte bleiben verfügbar.'));
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash.startsWith('post/'))detail(hash.slice(5));else if(['feed','trade','activities','profile'].includes(hash))navigate(hash);});
render();
const recovering=new URLSearchParams(location.hash.slice(1)).get('type')==='recovery';
if(configured){api.verifyCallback().then(async user=>{if(user?.email_confirmed_at){await loadLive(user);if(recovering)modal('Neues Passwort',`<p>Wähle ein neues Passwort mit mindestens 12 Zeichen.</p><form id="password-form"><label>Neues Passwort<input name="password" type="password" autocomplete="new-password" minlength="12" required></label><div class="form-error" id="password-error" role="alert"></div><button type="submit" class="btn primary full">Passwort speichern</button></form>`);}else if(user){await api.logout();authModal();}else authModal();}).catch(error=>{toast(error.message);authModal();});}
if(location.hash.startsWith('#post/'))detail(location.hash.slice(6));
if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register(new URL('../sw.js',import.meta.url)).catch(()=>{});

async function syncLive(){if(isDemo()||state.overlay||document.hidden||state.loading)return;try{const [posts,userState,memberships]=await Promise.all([api.posts(),api.state(state.user.id),api.memberships()]);if(state.overlay||isDemo())return;state.posts=posts.map(p=>({...p,price:Number(p.price||0),likes:Number(p.likes||0),join_count:memberships.filter(m=>m.post_id===p.id).length}));Object.assign(state,userState);const input=document.activeElement;if(input?.tagName==='INPUT')return;render();}catch{}}
setInterval(syncLive,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncLive();});

document.addEventListener('change',async event=>{
 if(event.target.name==='category'&&$('#create-form')){const ride=event.target.value==='Mitfahren';const fields=$('#ride-fields');if(fields){fields.hidden=!ride;fields.querySelectorAll('input').forEach(input=>{input.disabled=!ride;if(input.name==='ride_destination')input.required=ride;});const capacity=$('[name=capacity]');if(capacity){capacity.min=ride?'1':'2';capacity.max=ride?'8':'500';capacity.required=ride;}saveDraft(false);}return;}

 const kind=event.target.id==='profile-photo'?'profile':event.target.id==='post-photo'?'post':null;if(!kind)return;
 const file=event.target.files?.[0];if(!file)return;const target=event.target;target.disabled=true;
 try{const photo=await preparePhoto(file,kind==='profile'?110000:200000);if(kind==='profile')state.profilePhotoDraft=photo;else state.postPhotoDraft=photo;const box=$(`#${kind}-photo-preview`);if(box)box.innerHTML=`<img src="${e(photo)}" alt="Ausgewähltes Foto">`;if(kind==='post')saveDraft(false);}catch(error){toast(error.message);}finally{if(target.isConnected)target.disabled=false;}
});
window.addEventListener('storage',event=>{
 if(event.key!=='fhv-demo-v2'||!isDemo()||!event.newValue)return;
 try{const value=JSON.parse(event.newValue);if(value.version!==2)return;Object.assign(demoWorld,value);state.user={...demoPerson(demoWorld,state.user.id)};const a=demoWorld.accounts[state.user.id]||emptyDemoAccount();Object.assign(state,a,{posts:hydrateDemoPosts(demoWorld),chats:demoWorld.chats,messages:demoWorld.messages,comments:demoWorld.comments});if(state.currentChat)loadMessages(state.currentChat);else if(!state.overlay)render();}catch{}
});
